-- Generated from public/statues.geojson. Re-run npm run seed:supabase after local data changes.
on conflict (external_id) do update set name = excluded.name, province = excluded.province, city = excluded.city, address = excluded.address, longitude = excluded.longitude, latitude = excluded.latitude, "desc" = excluded."desc", background = excluded.background, year = excluded.year, image_url = excluded.image_url, source = excluded.source, verification_status = excluded.verification_status, updated_at = now();
